def wsg_cipher(input_bytes: bytes, key_bytes: bytes) -> bytes:
    """
    Compute WSG cipher output.

    This is the low-level cryptographic primitive used inside the WSG SDK.
    It's a fully-unrolled SPN (Substitution-Permutation Network) that takes
    8 bytes of input + 10 bytes of key and produces 8 bytes of output.

    Args:
        input_bytes: 8 bytes of input data
        key_bytes: 10 bytes of session key

    Returns:
        8 bytes of signature output
    """
    assert len(input_bytes) == 8 and len(key_bytes) == 10

    # Virtual memory layout
    SP_ADDR = 0x10000000
    INPUT_ADDR = 0x20000000
    KEYS_ADDR = 0x30000000
    OUTPUT_ADDR = 0x40000000
    TLS_ADDR = 0x50000000
    SBOX_ADDR = 0x60000000
    ORIG_SBOX = 0x6fad24bac0  # original runtime S-box address

    # Register file: x[0]-x[30], x[31]=sp
    x = [0] * 32
    x[31] = SP_ADDR
    x[0] = KEYS_ADDR
    x[1] = INPUT_ADDR
    x[2] = OUTPUT_ADDR
    x[30] = 0xDEAD0000
    tpidr = TLS_ADDR

    # Memory
    mem = {}
    for i, b in enumerate(input_bytes): mem[INPUT_ADDR + i] = b
    for i, b in enumerate(key_bytes): mem[KEYS_ADDR + i] = b
    for i in range(8): mem[OUTPUT_ADDR + i] = 0
    for t in range(10):
        for j in range(256): mem[SBOX_ADDR + t*256 + j] = SBOX[j]
    canary = 0xCAFEBABEDEADBEEF
    for i in range(8): mem[TLS_ADDR + 0x28 + i] = (canary >> (i*8)) & 0xFF

    # Memory access
    def rb(a): return mem.get(a, 0)
    def rh(a): return rb(a) | (rb(a+1) << 8)
    def rw(a): return rb(a)|(rb(a+1)<<8)|(rb(a+2)<<16)|(rb(a+3)<<24)
    def rd(a): return rw(a) | (rw(a+4) << 32)
    def wb(a, v): mem[a] = v & 0xFF
    def ww(a, v):
        for i in range(4): wb(a+i, (v>>(i*8))&0xFF)
    def wd(a, v):
        for i in range(8): wb(a+i, (v>>(i*8))&0xFF)

    M64 = 0xFFFFFFFFFFFFFFFF
    M32 = 0xFFFFFFFF

    def gx(i): return x[i] & M64
    def gw(i): return x[i] & M32
    def sx(i, v): x[i] = v & M64
    def sw(i, v): x[i] = v & M32

    for op in _OPS:
        kind = op[0]

        if kind == "SET_X0_0xD":
            x[0] = 0xd
            continue

        if kind == "MRS":
            sx(op[1], tpidr)
            continue

        if kind == "MOV":
            dst, w, st, sv = op[1], op[2], op[3], op[4]
            if st == "REG":
                v = gw(sv) if w else gx(sv)
            else:
                v = sv & (M32 if w else M64)
            if w: sw(dst, v)
            else: sx(dst, v)
            continue

        if kind == "MVN":
            dst, w, st, sv = op[1], op[2], op[3], op[4]
            v = gx(sv) if st == "REG" else sv
            m = M32 if w else M64
            if w: sw(dst, (~v) & m)
            else: sx(dst, (~v) & m)
            continue

        if kind == "MOVK":
            dst, imm, shift = op[1], op[2], op[3]
            v = gx(dst)
            mask = 0xFFFF << shift
            sx(dst, (v & ~mask) | ((imm & 0xFFFF) << shift))
            continue

        if kind in ("EOR", "EON", "ORR", "AND", "BIC"):
            dst, w, s1, st, s2, sh = op[1], op[2], op[3], op[4], op[5], op[6]
            m = M32 if w else M64
            v1 = gw(s1) if w else gx(s1)
            if st == "REG":
                v2 = gw(s2) if w else gx(s2)
                if sh:
                    if sh[0] == "LSL": v2 = (v2 << sh[1]) & m
                    elif sh[0] == "LSR": v2 = v2 >> sh[1]
            else:
                v2 = s2 & m
            if kind == "EOR": r = v1 ^ v2
            elif kind == "EON": r = ~(v1 ^ v2)
            elif kind == "ORR": r = v1 | v2
            elif kind == "AND": r = v1 & v2
            elif kind == "BIC": r = v1 & (~v2)
            if w: sw(dst, r & m)
            else: sx(dst, r & m)
            continue

        if kind in ("LSR", "LSL"):
            dst, w, src, amt = op[1], op[2], op[3], op[4]
            v = gw(src) if w else gx(src)
            if isinstance(amt, list): a = gx(amt[1]) if amt[0] == "REG" else amt
            else: a = amt
            if kind == "LSR": r = v >> a
            else: r = v << a
            m = M32 if w else M64
            if w: sw(dst, r & m)
            else: sx(dst, r & m)
            continue

        if kind in ("ADD", "SUB"):
            dst, w, s1, st, sv = op[1], op[2], op[3], op[4], op[5]
            v1 = gw(s1) if w else gx(s1)
            v2 = sv if st == "IMM" else (gw(sv) if w else gx(sv))
            if kind == "ADD": r = v1 + v2
            else: r = v1 - v2
            m = M32 if w else M64
            if w: sw(dst, r & m)
            else: sx(dst, r & m)
            continue

        if kind in ("ADRP", "ADR"):
            dst, addr = op[1], op[2]
            # Remap original SBOX addresses to our virtual layout
            if abs(addr - ORIG_SBOX) < 0x10000:
                sx(dst, SBOX_ADDR + (addr - ORIG_SBOX))
            else:
                sx(dst, addr)
            continue

        if kind == "SBFIZ":
            dst, src, lsb, width = op[1], op[2], op[3], op[4]
            v = gx(src)
            mask_w = (1 << width) - 1
            v = v & mask_w
            if v & (1 << (width-1)): v -= (1 << width)
            sx(dst, (v << lsb) & M64)
            continue

        if kind == "BFXIL":
            dst, src, lsb, width = op[1], op[2], op[3], op[4]
            dv = gx(dst)
            sv = gx(src)
            extracted = (sv >> lsb) & ((1 << width) - 1)
            mask_w = (1 << width) - 1
            sx(dst, (dv & ~mask_w) | extracted)
            continue

        if kind == "REV":
            dst, w, src = op[1], op[2], op[3]
            v = gw(src) if w else gx(src)
            if w:
                r = struct.unpack(">I", struct.pack("<I", v & M32))[0]
            else:
                r = struct.unpack(">Q", struct.pack("<Q", v & M64))[0]
            if w: sw(dst, r)
            else: sx(dst, r)
            continue

        if kind == "REV16":
            dst, w, src = op[1], op[2], op[3]
            v = gw(src) if w else gx(src)
            if w:
                b0,b1,b2,b3 = v&0xFF,(v>>8)&0xFF,(v>>16)&0xFF,(v>>24)&0xFF
                r = b1|(b0<<8)|(b3<<16)|(b2<<24)
            else:
                r = 0
                for ii in range(4):
                    hw = (v >> (ii*16)) & 0xFFFF
                    r |= (((hw>>8)&0xFF)|((hw&0xFF)<<8)) << (ii*16)
            if w: sw(dst, r)
            else: sx(dst, r)
            continue

        if kind == "LOAD":
            dst, w, size, base, index, disp = op[1], op[2], op[3], op[4], op[5], op[6]
            addr = gx(base) if base is not None else 0
            if index:
                idx_reg, idx_w = index[0], index[1]
                addr += gw(idx_reg) if idx_w else gx(idx_reg)
            addr += disp
            if size == 1: v = rb(addr)
            elif size == 2: v = rh(addr)
            elif size == 4: v = rw(addr)
            else: v = rd(addr)
            if w: sw(dst, v)
            else: sx(dst, v)
            continue

        if kind == "LDP":
            d1, d2, w, base, disp = op[1], op[2], op[3], op[4], op[5]
            addr = gx(base) if base is not None else 0
            addr += disp
            if w:
                sw(d1, rw(addr)); sw(d2, rw(addr+4))
            else:
                sx(d1, rd(addr)); sx(d2, rd(addr+8))
            continue

        if kind == "STORE":
            src, w, size, base, index, disp = op[1], op[2], op[3], op[4], op[5], op[6]
            addr = gx(base) if base is not None else 0
            if index:
                idx_reg, idx_w = index[0], index[1]
                addr += gw(idx_reg) if idx_w else gx(idx_reg)
            addr += disp
            v = gw(src) if w else gx(src)
            if size == 1: wb(addr, v)
            elif size == 4: ww(addr, v)
            else: wd(addr, v)
            continue

        if kind == "STP":
            s1, s2, w, base, disp = op[1], op[2], op[3], op[4], op[5]
            addr = gx(base) if base is not None else 0
            addr += disp
            v1 = gw(s1) if w else gx(s1)
            v2 = gw(s2) if w else gx(s2)
            if w: ww(addr, v1); ww(addr+4, v2)
            else: wd(addr, v1); wd(addr+8, v2)
            continue

    return bytes(rb(OUTPUT_ADDR + i) for i in range(8))


if __name__ == "__main__":
    import sys
    import time

    if len(sys.argv) == 3:
        inp = bytes.fromhex(sys.argv[1])
        key = bytes.fromhex(sys.argv[2])
        result = wsg_cipher(inp, key)
        print(result.hex())
    else:
        # Self-test
        inp = bytes.fromhex("dde61bdf7dc07556")
        key = bytes.fromhex("339022e9257f3ac4b5a5")
        expected = "1a6c10ef58db152f"
        t0 = time.time()
        result = wsg_cipher(inp, key)
        t1 = time.time()
        print(f"Input:    {inp.hex()}")
        print(f"Key:      {key.hex()}")
        print(f"Output:   {result.hex()}")
        print(f"Expected: {expected}")
        print(f"Match:    {result.hex() == expected}")
        print(f"Time:     {(t1-t0)*1000:.1f}ms")
